import itertools

solutions = []
for perm in itertools.permutations(range(8)):
    if perm[4] != 2:
        continue
    diffs = [abs(perm[i+1] - perm[i]) for i in range(7)]
    if sorted(diffs) == list(range(1,8)):
        solutions.append((perm, diffs))

print(f"Found {len(solutions)} solutions with x[4]=2")
for sol, diffs in solutions:
    print(sol, diffs)
